parameters.jsCode:
const body = $json.body || $json;
const data = body.data || body;

const adSoyad = (data.adSoyad || data.name || 'İsimsiz Aday').trim();
const telefon = (data.telefon || data.phone || '-').trim();
const email = (data.email || '').trim().toLowerCase();
const pozisyon = (data.pozisyon || data.position || 'Genel Tesis Personeli').trim();
const deneyimYili = parseInt(data.deneyimYili || data.experience || 1, 10);
const ilce = (data.ilce || data.district || 'İstanbul').trim();
const notlar = (data.notlar || data.notes || '').toLowerCase();

// Sertifika & Nitelik Tespiti
const has5188 = notlar.includes('5188') || notlar.includes('özel güvenlik') || pozisyon.toLowerCase().includes('güvenlik');
const hasAtesci = notlar.includes('ateşçi') || notlar.includes('kazan') || notlar.includes('kalorifer');
const hasEhliyet = notlar.includes('ehliyet') || notlar.includes('b sınıfı');
const hasHijyen = notlar.includes('hijyen') || notlar.includes('temizlik sertifikası');

let uygunlukPuani = 60;
if (deneyimYili >= 3) uygunlukPuani += 15;
if (has5188 || hasAtesci) uygunlukPuani += 15;
if (hasEhliyet) uygunlukPuani += 10;

const candidateId = `ALOHR-${new Date().toISOString().slice(0,10).replace(/-/g,'')}-${Math.random().toString(36).substr(2, 5).toUpperCase()}`;

return [{
  json: {
    candidateId,
    adSoyad,
    telefon,
    email: email.includes('@') ? email : null,
    pozisyon,
    deneyimYili,
    ilce,
    sertifikalar: {
      guvenlik5188: has5188,
      atesciBelgesi: hasAtesci,
      surucuBelgesi: hasEhliyet,
      hijyenBelgesi: hasHijyen
    },
    uygunlukPuani,
    summary: `İK Başvuru: ${adSoyad} (${pozisyon} - ${ilce}) - Puan: ${uygunlukPuani}/100`
  }
}];
